-    ctx->Message_Digest[0] =
-                        (ctx->Message_Digest[0] + A) & 0xFFFFFFFF;
-    ctx->Message_Digest[1] =
-                        (ctx->Message_Digest[1] + B) & 0xFFFFFFFF;
-    ctx->Message_Digest[2] =
